	router.GET(options.BaseURL+"/tams/v1/flows", wrapper.GetFlows)
	router.HEAD(options.BaseURL+"/tams/v1/flows", wrapper.HeadFlows)
	router.DELETE(options.BaseURL+"/tams/v1/flows/:flowId", wrapper.DeleteFlow)
	router.GET(options.BaseURL+"/tams/v1/flows/:flowId", wrapper.GetFlow)
